WITH flattened_attrs AS (SELECT id, customer_id, coupon_codes, attributes, ship_to.zip AS ship_zip, SIZE(FILTER(items, item -> item.qty >= 3)) AS bulk_lines, ARRAY_CONTAINS(MAP_KEYS(attributes), 'device') AS has_device, TRANSFORM(items, item -> item.product_id) AS product_ids, COALESCE(attributes['utm_source'], 'direct') AS utm_source_or_default FROM carts) SELECT CASE WHEN bulk_lines >= 3 THEN 'PREMIUM' ELSE 'STANDARD' END AS bulk_lines_tier, PERCENTILE_APPROX(bulk_lines, 0.95) AS bulk_lines_p95, APPROX_PERCENTILE(bulk_lines, 0.5) AS bulk_lines_p50, ROUND(AVG(bulk_lines), 2) AS avg_bulk_lines FROM flattened_attrs GROUP BY bulk_lines_tier ORDER BY bulk_lines_p50 DESC NULLS FIRST;
